import functools
import inspect
from typing import ForwardRef
from fastapi.dependencies.utils import get_typed_signature

# We need to simulate two different modules. 
# We can do this by creating a function that defines another function.

def create_wrapper():
    def wrapper(func):
        @functools.wraps(func)
        def wrapped(*args, **kwargs):
            return func(*args, **kwargs)
        return wrapped
    return wrapper

def create_target():
    class B:
        pass
    def func(x: "B"):
        pass
    return func, B

target_func, B_class = create_target()
wrapper_func = create_wrapper()
wrapped_func = wrapper_func(target_func)

print(f"Wrapped func globals: {wrapped_func.__globals__}")
print(f"Target func globals: {target_func.__globals__}")

try:
    sig = get_typed_signature(wrapped_func)
    print("Success!")
    print(f"Signature: {sig}")
except Exception as e:
    print(f"Failed with error: {e}")
    import traceback
    traceback.print_exc()

